        Check(in.StreamPos == 104 && in.SourceChunkBytesRemaining == 4 && in.CurrentSourcePtr == chunk + 4, "load advances the stream by 4");
        Check(in.OverflowCalls == 0, "a full chunk needs no overflow read");
